  /* =======================================================
  PI LOGIN
  ======================================================= */

  const [loginBusy, setLoginBusy] = useState(false);

  // Pi Browser authentication uses the Pi SDK.
  // The SDK must be initialized once before Pi.authenticate().
  useEffect(() => {
    let cancelled = false;
    let attempts = 0;

    const preparePi = () => {
      if (cancelled) return;

      const pi = (window as any).Pi;
      if (pi) {
        try {
          Promise.resolve(
            pi.init({ version: "2.0", sandbox: false })
          ).catch((error: unknown) =>
            console.warn("Pi SDK init:", error)
          );
        } catch (error) {
          console.warn("Pi SDK init:", error);
        }
        return;
      }

      attempts += 1;
      if (attempts < 150) {
        window.setTimeout(preparePi, 100);
      }
    };

    preparePi();

    return () => {
      cancelled = true;
    };
  }, []);

  const loginWithPi = async () => {
    if (loginBusy) return;

    setLoginBusy(true);

    try {
      const waitForPi = () =>
        new Promise<any>((resolve, reject) => {
          let attempts = 0;

          const check = () => {
            const pi = (window as any).Pi;

            if (pi) {
              resolve(pi);
              return;
            }

            attempts += 1;
            if (attempts >= 150) {
              reject(new Error(t("piSdkError")));
              return;
            }

            window.setTimeout(check, 100);
          };

          check();
        });

      const pi = await Promise.race([
        waitForPi(),
        new Promise((_, reject) =>
          window.setTimeout(
            () => reject(new Error(t("piSdkError"))),
            15000
          )
        ),
      ]);

      const auth = await pi.authenticate(
        ["username"],
        (payment: any) => {
          console.warn(
            "Incomplete Pi payment found during authentication:",
            payment?.identifier
          );
        }
      );

      if (!auth?.user?.username || !auth?.accessToken) {
        throw new Error(t("piUserError"));
      }

      const controller = new AbortController();
      const backendTimer = window.setTimeout(
        () => controller.abort(),
        10000
      );

      let response: Response;
      try {
        response = await fetch(`${backendUrl}/user/signin`, {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
          },
          credentials: "include",
          signal: controller.signal,
          body: JSON.stringify({
            authResult: auth,
          }),
        });
      } finally {
        window.clearTimeout(backendTimer);
      }

      const data = await response.json().catch(() => ({}));

      if (!response.ok) {
        throw new Error(data?.message || t("backendError"));
      }

      setSignedIn(true);
      setUsername(auth.user.username);

      const welcome =
        appLanguage === "Turkish"
          ? "Hoş geldin"
          : appLanguage === "English"
          ? "Welcome"
          : appLanguage === "Arabic"
          ? "مرحباً"
          : appLanguage === "Spanish"
          ? "Bienvenido"
          : appLanguage === "French"
          ? "Bienvenue"
          : appLanguage === "German"
          ? "Willkommen"
          : appLanguage === "Portuguese"
          ? "Bem-vindo"
          : appLanguage === "Russian"
          ? "Добро пожаловать"
          : appLanguage === "Chinese"
          ? "欢迎"
          : "स्वागत है";

      setStatus(`✅ ${welcome} @${auth.user.username}`);
    } catch (error) {
      console.error("Pi login error:", error);

      setSignedIn(false);
      setUsername("");

      const message = error instanceof Error ? error.message : "";
      const timeoutError =
        error instanceof DOMException && error.name === "AbortError";

      setStatus(
        timeoutError
          ? `❌ ${t("backendError")}`
          : message
          ? `❌ ${message}`
          : `❌ ${t("loginFailed")}`
      );
    } finally {
      setLoginBusy(false);
    }
  };

